  "robustness_explanation": {
    "summary": "The ordering holds in about 56% of variations, so this sits on the fragile side based on current estimates.",
    "primary_risk": "The link from Delivery Throughput to Operating Margin is the main source of fragility here.",
    "stability_factors": [
      "Staff Retention shows a reasonably well evidenced connection to Operating Margin."
    ],
    "fragility_factors": [
      "The link from Delivery Throughput to Operating Margin could shift which option more runs support."
    ]
  },
  "readiness_rationale": "Two things still hold this back: the close split between the options and the unsettled link from Delivery Throughput to Operating Margin, which together leave the comparison open to change.",
