    "fac_throughput": {
      "specific_action": "Pull recent delivery throughput records and compare actual completion rates against the modelled estimate.",
      "rationale": "Throughput is the main swing factor behind this comparison, so firming it up directly sharpens the result.",
      "evidence_type": "internal_data",
      "decision_hygiene": "Estimate the current throughput rate yourself before checking the records."
    }
  },
  "scenario_contexts": {
    "edge_throughput_margin": {
      "trigger_description": "If Delivery Throughput weakens relative to the connection assumed with Operating Margin...",
      "consequence": "...then the most runs would support Keep Current Schedule rather than Move to Four Day Week."
    }
  },
  "flip_thresholds": [
    {
      "factor_id": "fac_throughput",
      "factor_label": "Delivery Throughput",
      "current_display": "44%",
      "flip_display": "49%",
